// Query with offset
const GET_USERS = gql`
  query GetUsers($offset: Int!, $limit: Int!) {
    users(offset: $offset, limit: $limit) {
      id
      name
    }
  }
`;

const cache = new InMemoryCache({
  typePolicies: {
    Query: {
      fields: {
        users: {
          keyArgs: ['filter'],
          merge(existing, incoming, { args }) {
            if (args?.after) {
              // Append for pagination
              return { ...incoming, edges: [...existing.edges, ...incoming.edges] };
            }
            return incoming;
          }
        }
      }
    }
  }
});
